{v:'VER',what:'the Heavy helmet crest is not a neon bar: on the Toxic scheme the helmet adds no neon green pixels (char-art brief: the neon green bar reads like a glitch)',
 run:function(){
   if(typeof drawOp!=='function'||typeof COSKEY==='undefined') return 'SKIP: no drawOp';
   var keepW=wc, keepOwned=cosOwned, keepH=P[COSKEY.hat], keepS=P[COSKEY.scheme], keepO=P[COSKEY.outfit], cv, x2, neon, withHat, bare;
   neon=function(x2){ var d=x2.getImageData(0,0,128,128).data, n=0, i; for(i=0;i<d.length;i+=4){ if(d[i+3]>200&&d[i+1]>=190&&d[i]<=190&&d[i+2]<=120&&d[i+1]-d[i]>50) n++; } return n; };
   try{
     __runPrep(); __topClear(); __resetCfg(); __pinDefaults(0); __cleanProfile();
     cv=document.createElement('canvas'); cv.width=128; cv.height=128; x2=cv.getContext('2d');
     cosOwned=function(){ return true; };
     P[COSKEY.scheme]='schtoxic'; P[COSKEY.outfit]='outnone';
     wc=x2;
     P[COSKEY.hat]='none';
     x2.setTransform(1,0,0,1,0,0); x2.clearRect(0,0,128,128); x2.translate(64,100); x2.scale(1.4,1.4);
     drawOp(0,0,0,0,'#242832',0,0,'none',0,{hero:1,moving:false,sprint:false,ads:false,hurt:0,rl:0,own:{wep:null}});
     bare=neon(x2);
     P[COSKEY.hat]='heavyhelm';
     x2.setTransform(1,0,0,1,0,0); x2.clearRect(0,0,128,128); x2.translate(64,100); x2.scale(1.4,1.4);
     drawOp(0,0,0,0,'#242832',0,0,'none',0,{hero:1,moving:false,sprint:false,ads:false,hurt:0,rl:0,own:{wep:null}});
     withHat=neon(x2);
     if(withHat-bare>3) return 'the Heavy helmet adds '+(withHat-bare)+' neon green pixels (a bar on the dome)';
     return null;
   } finally {
     wc=keepW; cosOwned=keepOwned;
     if(keepH===undefined) delete P[COSKEY.hat]; else P[COSKEY.hat]=keepH;
     if(keepS===undefined) delete P[COSKEY.scheme]; else P[COSKEY.scheme]=keepS;
     if(keepO===undefined) delete P[COSKEY.outfit]; else P[COSKEY.outfit]=keepO;
     __topClear();
   } }},
